#!/usr/bin/env python3
"""Regenerates ../profanity_words_data.h from ldnoobw_en.txt.

Run this (from anywhere, no dependencies beyond the stdlib) after
editing ldnoobw_en.txt - e.g. to pull in an updated upstream list or
add/remove entries for a specific deployment. Not part of the Arduino
build itself; the .h file it produces is what actually gets compiled.

Usage: python3 generate_profanity_data.py
"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "ldnoobw_en.txt")
DEST = os.path.join(HERE, "..", "profanity_words_data.h")


def c_escape(word: str) -> str:
    return word.replace("\\", "\\\\").replace('"', '\\"')


def main():
    with open(SRC, "r", encoding="utf-8") as f:
        words = [line.strip().lower() for line in f if line.strip()]
    # Stable, de-duplicated, sorted purely for readability/diffability -
    # matching order doesn't matter since profanity_filter.cpp checks
    # every entry regardless of position.
    words = sorted(set(words))

    lines = []
    lines.append("#pragma once")
    lines.append("")
    lines.append("// AUTO-GENERATED by thirdparty/generate_profanity_data.py from")
    lines.append("// thirdparty/ldnoobw_en.txt - do not hand-edit this file, edit the")
    lines.append("// .txt and re-run the script instead. See thirdparty/README.md for")
    lines.append("// the word list's source and license (CC BY 4.0, Shutterstock/LDNOOBW).")
    lines.append("")
    lines.append("#include <Arduino.h>")
    lines.append("")
    for i, w in enumerate(words):
        lines.append(f'const char kProfanityWord{i}[] PROGMEM = "{c_escape(w)}";')
    lines.append("")
    lines.append(f"#define PROFANITY_WORD_COUNT {len(words)}")
    lines.append("")
    lines.append("const char* const kProfanityWords[PROFANITY_WORD_COUNT] PROGMEM = {")
    for i in range(len(words)):
        lines.append(f"  kProfanityWord{i},")
    lines.append("};")
    lines.append("")

    with open(DEST, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print(f"Wrote {DEST} ({len(words)} entries)")


if __name__ == "__main__":
    main()
